import{u as n,C as s,c as l,o as r,j as a,G as d,e as h,al as u,a as t,k as c}from"./chunks/framework.CT7RwC5a.js";const m={key:0},g=JSON.parse('{"title":"PX4-Autopilot Головна нотатка щодо релізу","description":"","frontmatter":{},"headers":[],"relativePath":"uk/releases/main.md","filePath":"uk/releases/main.md"}'),p={name:"uk/releases/main.md"},_=Object.assign(p,{setup(f){const{site:o}=n();return(b,e)=>{const i=s("Badge");return r(),l("div",null,[e[1]||(e[1]=a("h1",{id:"px4-autopilot-головна-нотатка-щодо-релізу",tabindex:"-1"},[t("PX4-Autopilot Головна нотатка щодо релізу "),a("a",{class:"header-anchor",href:"#px4-autopilot-головна-нотатка-щодо-релізу","aria-label":'Permalink to "PX4-Autopilot Головна нотатка щодо релізу"'},"​")],-1)),d(i,{type:"danger",text:"Alpha"}),c(o).title!=="PX4 Guide (main)"?(r(),l("div",m,e[0]||(e[0]=[a("div",{class:"custom-block danger"},[a("p",{class:"custom-block-title"},[t("This page is on a release branch, and hence probably out of date. "),a("a",{href:"https://docs.px4.io/main/en/releases/main.html"},"See the latest version"),t(".")])],-1)]))):h("",!0),e[2]||(e[2]=u('<p>This contains changes to PX4 <code>main</code> branch since the last major release (<a href="./../releases/1.16.html">PX v1.16</a>).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 v1.16 is in candidate-release testing, pending release. Update these notes with features that are going to be in <code>main</code> but not the PX4 v1.16 release.</p></div><h2 id="прочитаите-перед-оновленням" tabindex="-1">Прочитайте перед оновленням <a class="header-anchor" href="#прочитаите-перед-оновленням" aria-label="Permalink to &quot;Прочитайте перед оновленням&quot;">​</a></h2><p>TBD …</p><p>Please continue reading for <a href="#upgrade-guide">upgrade instructions</a>.</p><h2 id="основні-зміни" tabindex="-1">Основні зміни <a class="header-anchor" href="#основні-зміни" aria-label="Permalink to &quot;Основні зміни&quot;">​</a></h2><ul><li>Уточнюється</li></ul><h2 id="інструкціі-для-оновлення" tabindex="-1">Інструкції для оновлення <a class="header-anchor" href="#інструкціі-для-оновлення" aria-label="Permalink to &quot;Інструкції для оновлення&quot;">​</a></h2><h2 id="інші-зміни" tabindex="-1">Інші зміни <a class="header-anchor" href="#інші-зміни" aria-label="Permalink to &quot;Інші зміни&quot;">​</a></h2><h3 id="підтримка-обладнання" tabindex="-1">Підтримка обладнання <a class="header-anchor" href="#підтримка-обладнання" aria-label="Permalink to &quot;Підтримка обладнання&quot;">​</a></h3><ul><li>Уточнюється</li></ul><h3 id="загальні" tabindex="-1">Загальні <a class="header-anchor" href="#загальні" aria-label="Permalink to &quot;Загальні&quot;">​</a></h3><ul><li><a href="./../advanced_config/bootloader_update.html#qgc-bootloader-update-sys-bl-update">QGroundControl Bootloader Update</a> via the <a href="./../advanced_config/parameter_reference.html#SYS_BL_UPDATE">SYS_BL_UPDATE</a> parameter has been re-enabled after being broken for a number of releases. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25032" target="_blank" rel="noreferrer">PX4-Autopilot#25032: build: romf: fix generation of rc.board_bootloader_upgrade</a>).</li></ul><h3 id="управління" tabindex="-1">Управління <a class="header-anchor" href="#управління" aria-label="Permalink to &quot;Управління&quot;">​</a></h3><ul><li>Added new flight mode(s): <a href="./../flight_modes_mc/altitude_cruise.html">Altitude Cruise (MC)</a>, Altitude Cruise (FW). For fixed-wing the mode behaves the same as Altitude mode but you can disable the manual control loss failsafe. (PX4-Autopilot#25435: Add new flight mode: Altitude Cruise ).</li></ul><h3 id="оцінки" tabindex="-1">Оцінки <a class="header-anchor" href="#оцінки" aria-label="Permalink to &quot;Оцінки&quot;">​</a></h3><ul><li>Уточнюється</li></ul><h3 id="датчики" tabindex="-1">Датчики <a class="header-anchor" href="#датчики" aria-label="Permalink to &quot;Датчики&quot;">​</a></h3><ul><li>Add <a href="./../sensor/sbgecom.html">sbgECom INS driver</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/24137" target="_blank" rel="noreferrer">PX4-Autopilot#24137</a>)</li></ul><h3 id="симуляція" tabindex="-1">Симуляція <a class="header-anchor" href="#симуляція" aria-label="Permalink to &quot;Симуляція&quot;">​</a></h3><ul><li>Overhaul rover simulation: <ul><li>Add synthetic differential rover model: <a href="https://github.com/PX4/PX4-gazebo-models/pull/107" target="_blank" rel="noreferrer">PX4-gazebo-models#107</a></li><li>Add synthetic mecanum rover model: <a href="https://github.com/PX4/PX4-gazebo-models/pull/113" target="_blank" rel="noreferrer">PX4-gazebo-models#113</a></li><li>Update synthetic ackermann rover model: <a href="https://github.com/PX4/PX4-gazebo-models/pull/117" target="_blank" rel="noreferrer">PX4-gazebo-models#117</a></li></ul></li></ul><h3 id="ethernet" tabindex="-1">Ethernet <a class="header-anchor" href="#ethernet" aria-label="Permalink to &quot;Ethernet&quot;">​</a></h3><ul><li>Уточнюється</li></ul><h3 id="uxrce-dds-ros2" tabindex="-1">uXRCE-DDS / ROS2 <a class="header-anchor" href="#uxrce-dds-ros2" aria-label="Permalink to &quot;uXRCE-DDS / ROS2&quot;">​</a></h3><ul><li><a href="./../ros2/px4_ros2_control_interface.html">PX4 ROS 2 Interface Library</a> support for <a href="./../ros2/px4_ros2_control_interface.html#fixed-wing-lateral-and-longitudinal-setpoint-fwlaterallongitudinalsetpointtype">Fixed Wing lateral/longitudinal setpoint</a> (<code>FwLateralLongitudinalSetpointType</code>) and <a href="./../ros2/px4_ros2_control_interface.html#controlling-a-vtol">VTOL transitions</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24056" target="_blank" rel="noreferrer">PX4-Autopilot#24056</a>).</li><li><a href="./../ros2/px4_ros2_control_interface.html">PX4 ROS 2 Interface Library</a> support for <a href="./../ros2/px4_ros2_waypoint_missions.html">ROS-based waypoint missions</a>.</li></ul><h3 id="mavlink" tabindex="-1">MAVLink <a class="header-anchor" href="#mavlink" aria-label="Permalink to &quot;MAVLink&quot;">​</a></h3><ul><li>Уточнюється</li></ul><h3 id="мульти-ротор" tabindex="-1">Мульти-Ротор <a class="header-anchor" href="#мульти-ротор" aria-label="Permalink to &quot;Мульти-Ротор&quot;">​</a></h3><ul><li>Removed parameters <code>MPC_{XY/Z/YAW}_MAN_EXPO</code> and use default value instead, as they were not deemed necessary anymore. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25435" target="_blank" rel="noreferrer">PX4-Autopilot#25435: Add new flight mode: Altitude Cruise</a>).</li><li>Renamed <code>MPC_HOLD_DZ</code> to <code>MAN_DEADZONE</code> to have it globally available in modes that allow for a dead zone. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25435" target="_blank" rel="noreferrer">PX4-Autopilot#25435: Add new flight mode: Altitude Cruise</a>).</li></ul><h3 id="vtol" tabindex="-1">VTOL <a class="header-anchor" href="#vtol" aria-label="Permalink to &quot;VTOL&quot;">​</a></h3><ul><li>Уточнюється</li></ul><h3 id="літак-з-фіксованим-крилом" tabindex="-1">Літак з фіксованим крилом <a class="header-anchor" href="#літак-з-фіксованим-крилом" aria-label="Permalink to &quot;Літак з фіксованим крилом&quot;">​</a></h3><ul><li><a href="./../flight_modes_fw/takeoff.html">Fixed Wing Takeoff mode</a> will now keep climbing with level wings on position loss. A target takeoff waypoint can be set to control takeoff course and loiter altitude. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25083" target="_blank" rel="noreferrer">PX4-Autopilot#25083</a>).</li></ul><h3 id="ровер" tabindex="-1">Ровер <a class="header-anchor" href="#ровер" aria-label="Permalink to &quot;Ровер&quot;">​</a></h3><ul><li>Removed deprecated rover module (<a href="https://github.com/PX4/PX4-Autopilot/pull/25054" target="_blank" rel="noreferrer">PX4-Autopilot#25054</a>).</li><li>Add support for <a href="./../flight_modes_rover/api.html">Apps &amp; API</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/25074" target="_blank" rel="noreferrer">PX4-Autopilot#25074</a>, <a href="https://github.com/Auterion/px4-ros2-interface-lib/pull/140" target="_blank" rel="noreferrer">PX4-ROS2-Interface-Lib#140</a>).</li><li>Update <a href="./../frames_rover/#simulation">rover simulation</a> (<a href="https://github.com/PX4/PX4-Autopilot/pull/25644" target="_blank" rel="noreferrer">PX4-Autopilot#25644</a>) (see <a href="#simulation">Simulation</a> release note for details).</li></ul><h3 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h3><ul><li>Уточнюється</li></ul>',37))])}}});export{g as __pageData,_ as default};
